#[AsMonologProcessor]
final class CorrelationId implements ResetInterface
{
    private ?string $id = null;

    public function get(): string
    {
        return $this->id ??= Uuid::v7()->toRfc4122();
    }

    public function set(string $id): void
    {
        $this->id = $id;
    }

    // Monolog calls this before writing every log record
    public function __invoke(LogRecord $record): LogRecord
    {
        $record->extra['correlation_id'] = $this->get();

        return $record;
    }

    public function reset(): void
    {
        $this->id = null;
    }
}

final class CorrelationIdListener
{
    public function __construct(private readonly CorrelationId $correlationId)
    {
    }

    #[AsEventListener(priority: 1024)]
    public function onRequest(RequestEvent $event): void
    {
        $incoming = $event->getRequest()->headers->get('X-Correlation-Id');

        // if an upstream service sent a number, reuse it, but validate it
        if ($event->isMainRequest() && null !== $incoming && Uuid::isValid($incoming)) {
            $this->correlationId->set($incoming);
        }
    }

    #[AsEventListener]
    public function onResponse(ResponseEvent $event): void
    {
        $event->getResponse()->headers->set('X-Correlation-Id', $this->correlationId->get());
    }
}

final class CorrelationIdStamp implements StampInterface
{
    public function __construct(public readonly string $id)
    {
    }
}

final class CorrelationIdMiddleware implements MiddlewareInterface
{
    public function __construct(private readonly CorrelationId $correlationId)
    {
    }

    public function handle(Envelope $envelope, StackInterface $stack): Envelope
    {
        $stamp = $envelope->last(CorrelationIdStamp::class);

        if (null === $stamp) {
            // sending: stick the current number onto the message
            $envelope = $envelope->with(new CorrelationIdStamp($this->correlationId->get()));
        } elseif (null !== $envelope->last(ReceivedStamp::class)) {
            // in the worker: the message's number becomes the current one
            $this->correlationId->set($stamp->id);
        }

        return $stack->next()->handle($envelope, $stack);
    }
}

