#[AsDecorator(decorates: 'http_client')]
final class CorrelationIdHttpClient implements HttpClientInterface
{
    public function __construct(
        #[AutowireDecorated] private HttpClientInterface $inner,
        private readonly CorrelationId $correlationId,
    ) {
    }

    public function request(
        string $method,
        string $url,
        array $options = [],
    ): ResponseInterface {
        $options['headers']['X-Correlation-Id'] = $this->correlationId->get();

        return $this->inner->request($method, $url, $options);
    }

    public function stream(
        ResponseInterface|iterable $responses,
        ?float $timeout = null,
    ): ResponseStreamInterface {
        return $this->inner->stream($responses, $timeout);
    }

    public function withOptions(array $options): static
    {
        $clone = clone $this;
        $clone->inner = $this->inner->withOptions($options);

        return $clone;
    }
}

