final class RequestMetricsListener
{
    public function __construct(private readonly CollectorRegistry $registry)
    {
    }

    #[AsEventListener(priority: 1024)]
    public function onRequest(RequestEvent $event): void
    {
        $event->getRequest()->attributes->set('_started', microtime(true));
    }

    #[AsEventListener]
    public function onTerminate(TerminateEvent $event): void
    {
        $request = $event->getRequest();
        $route = (string) $request->attributes->get('_route', 'unknown');
        $status = (string) $event->getResponse()->getStatusCode();
        $seconds = microtime(true) - (float) $request->attributes->get('_started');

        $this->registry
            ->getOrRegisterCounter('shop', 'http_requests_total', 'Requests',
                ['method', 'route', 'status'])
            ->inc([$request->getMethod(), $route, $status]);

        $this->registry
            ->getOrRegisterHistogram('shop', 'http_request_duration_seconds', 'Latency',
                ['route'], [0.05, 0.1, 0.25, 0.5, 1, 2.5])
            ->observe($seconds, [$route]);
    }
}

#[Route('/metrics', methods: ['GET'])]
public function metrics(
    CollectorRegistry $registry,
    #[Autowire(service: 'messenger.transport.async')] MessageCountAwareInterface $async,
): Response {
    // gauge: how many jobs are waiting right now, read at every scrape
    $registry
        ->getOrRegisterGauge('shop', 'queue_depth', 'Messages waiting', ['queue'])
        ->set($async->getMessageCount(), ['async']);

    $text = (new RenderTextFormat())->render($registry->getMetricFamilySamples());

    return new Response($text, 200, ['Content-Type' => RenderTextFormat::MIME_TYPE]);
}

#[Route('/health/live', methods: ['GET'])]
public function live(): JsonResponse
{
    return new JsonResponse(['status' => 'up']); // no dependencies
}

#[Route('/health/ready', methods: ['GET'])]
public function ready(): JsonResponse
{
    $checks = [   // only what the app cannot work without
        'database' => fn () => $this->db->executeQuery('SELECT 1'),
        'cache' => fn () => $this->cache->getItem('health_probe'),
    ];

    $failed = [];
    foreach ($checks as $name => $check) {
        try {
            $check();
        } catch (\Throwable $e) {
            $failed[] = $name;
            $this->logger->error('health.failed', ['check' => $name, 'exception' => $e]);
        }
    }

    return new JsonResponse(
        ['status' => [] === $failed ? 'ready' : 'degraded'],
        [] === $failed ? 200 : 503,
    );
}

